import base64
import copy
import json

AGENT = {"name":"ops-agent","image":"registry.example.invalid/ops-agent:1.0",
         "resources":{"requests":{"cpu":"10m","memory":"16Mi"},
                      "limits":{"cpu":"100m","memory":"64Mi"}}}

def mutate(review):
    request = review["request"]
    response = {"uid":request["uid"], "allowed":True}
    output = {"apiVersion":"admission.k8s.io/v1", "kind":"AdmissionReview", "response":response}
    if (request.get("operation") != "CREATE" or request.get("namespace") != "app-a"
        or request.get("subResource", "") != ""
        or request.get("resource") != {"group":"","version":"v1","resource":"pods"}):
        return output
    pod = request.get("object", {})
    if pod.get("metadata", {}).get("annotations", {}).get("ops.example/inject") != "true":
        return output
    def deny(message):
        response.update(allowed=False,status={"code":422,"message":message})
        return output
    containers = pod.get("spec", {}).get("containers")
    if not isinstance(containers,list) or not containers:
        return deny("nonempty containers required")
    names = [c.get("name") if isinstance(c,dict) else None for c in containers]
    if any(not isinstance(n,str) or not n for n in names) or len(set(names))!=len(names):
        return deny("container names must be unique")
    for c in containers:
        if c["name"]=="ops-agent" and c!=AGENT:
            return deny("existing ops-agent conflicts with managed definition")
        resources=c.get("resources",{})
        if not isinstance(resources,dict) or not isinstance(resources.get("requests",{}),dict):
            return deny("resources and requests must be objects")
    patch=[]
    for i,c in enumerate(containers):
        if c["name"]=="ops-agent":
            continue
        path="/spec/containers/"+str(i)+"/resources"
        if "resources" not in c:
            patch.append({"op":"add","path":path,"value":{"requests":{"cpu":"100m","memory":"64Mi"}}})
        elif "requests" not in c["resources"]:
            patch.append({"op":"add","path":path+"/requests","value":{"cpu":"100m","memory":"64Mi"}})
        else:
            for name,value in (("cpu","100m"),("memory","64Mi")):
                if name not in c["resources"]["requests"]:
                    patch.append({"op":"add","path":path+"/requests/"+name,"value":value})
    if "ops-agent" not in names:
        patch.append({"op":"add","path":"/spec/containers/-","value":copy.deepcopy(AGENT)})
    if patch:
        response["patchType"]="JSONPatch"
        response["patch"]=base64.b64encode(json.dumps(patch,separators=(",",":")).encode()).decode()
    return output
